  "mainEntity": [
    {
      "@type": "Question",
      "name": "ما الفرق بين جرامية الورق وسُمكه، وأيهما أهم عند الطلب؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "الجرامية وزن والسُمك بُعد يُقاس بالميكرومتر. الأهم عند الطلب هو الجرامية لأنها اللغة الموحدة بين المشتري والمطبعة، والسُمك يتبع نوع الألياف والطلاء ويتغيّر حتى ضمن نفس الوزن."
      }
    },
    {
      "@type": "Question",
      "name": "هل ورق 80 جرام مناسب لطباعة الصور والمواد التسويقية؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "لا، الورق بهذا الوزن يُظهر ألوان الوجه الآخر من الخلف ويضعف عند الطي. الحد الأدنى المناسب للمواد الترويجية عادةً 120 جرام فأعلى."
      }
    },

    {
      "@type": "Question",
      "name": "ما الجرامية الموصى بها للكتالوجات والبروشورات الاحترافية؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "الصفحات الداخلية تعمل جيدًا على 120 أو 135 جرام، والأغلفة تحتاج جرامية أعلى مثل 250 أو 300 جرام. المزج بين الجراميتين هو الممارسة الشائعة في السوق المصرية."
      }
    },
    {
      "@type": "Question",
      "name": "ما الجرامية المناسبة لبطاقات العمل حتى تعطي انطباعًا احترافيًا؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "بطاقات العمل تحتاج 300 جرام كحد أدنى، ويستخدم كثيرون 350 جرام مع تشطيبات إضافية. الوزن الأقل يجعل البطاقة تنثني في المحفظة سريعًا."
      }
    },
    {
      "@type": "Question",
      "name": "كيف تؤثر زيادة الجرامية على تكلفة الطباعة الإجمالية؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "الورق الأثقل يستهلك مواد خام أكثر، ويزيد وزن الشحنة، ويرفع تكلفة التعبئة والتسليم. بعض التشطيبات مثل التغليف والطي تصبح أصعب مع الورق الثقيل وتحتاج ضبطًا إضافيًا يظهر في الفاتورة."
      }
    },
    {
      "@type": "Question",
      "name": "ما الفرق بين الورق المطفي والورق اللامع بنفس الجرامية؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "اللامع يبرز حدة الألوان وتفاصيل الصور، والمطفي يُريح العين ويقلل انعكاس الإضاءة. الاختيار بينهما يعتمد على غرض المطبوع لا على الجرامية."
      }
    }
  ]
